            'message_invalid' => 'پیام توسط تلگرام پذیرفته نشد',
            'telegram_auth'   => 'توکن ربات توسط تلگرام رد شد',
        ];
        $details = [
            'rate_limit'           => 'Too Many Requests',
            'timeout'              => 'Connection timeout',
            'dns'                  => 'DNS error',
            'refused'              => 'Connection refused',
            'connect'              => 'Connection failed',
            'reset'             => 'Connection reset',
            'ssl'                  => 'SSL error',
            'network'              => 'Network error',
            'no_response'          => 'No response',
            'invalid_response'     => 'Invalid response',
            'too_many_connections' => 'Too many connections',
            'db_refused'           => 'Connection refused',
            'db_lost'              => 'Lost connection',
            'db_gone'              => 'MySQL server has gone away',
            'db_error'             => 'Database connection error',
            'db_unavailable'       => 'Database unavailable',
            'worker_fatal'         => 'Worker stopped unexpectedly',
            'worker_exception'     => 'Worker error',
            'queue_unavailable'    => 'Queue file unavailable',
            'message_invalid'      => 'Message rejected by Telegram',
            'telegram_auth'        => 'Unauthorized',
        ];
        $reason = (string) ($info['pause_reason'] ?? 'system');
        $detailKey = (string) ($info['pause_detail'] ?? '');
        $detail = $details[$detailKey] ?? (preg_match('/^http_(\d{3})$/', $detailKey, $m) ? 'HTTP ' . $m[1] : '');
        $t = "\n⚠️ دلیل توقف : <b>" . ($titles[$reason] ?? $titles['system']) . "</b>\n";
        if ($detail !== '') {
            $t .= "🔎 جزئیات : <code>" . htmlspecialchars($detail, ENT_QUOTES, 'UTF-8') . "</code>\n";
        }
        $until = (int) ($info['pause_until'] ?? 0);
        if (!empty($info['manual_resume']) || $until <= 0) {
            $t .= "🖐 ادامه خودکار انجام نمی‌شود؛ برای ادامه روی «▶️ ادامه عملیات» بزنید.\n";
        } else {
            $t .= "⏳ ادامه خودکار پس از حدود <b>" . max(0, $until - time()) . "</b> ثانیه (در اجرای بعدی کرون)\n";
        }
        return $t;
    }
}


if (!function_exists('rx_host_profile_cache_path')) {
    function rx_host_profile_cache_path()
    {
        $root = defined('REFACTORED_LEGACY_ROOT') ? REFACTORED_LEGACY_ROOT
              : (defined('APP_ROOT_PATH') ? APP_ROOT_PATH : dirname(__DIR__, 3));
        $cronbot = $root . DIRECTORY_SEPARATOR . 'cronbot';
        $runtime = $cronbot . DIRECTORY_SEPARATOR . '.runtime';
        if (@is_dir($runtime) || @mkdir($runtime, 0775, true) || @is_dir($runtime)) {
            return $runtime . DIRECTORY_SEPARATOR . 'host_profile.json';
        }
        if (@is_dir($cronbot)) {
            return $cronbot . DIRECTORY_SEPARATOR . 'host_profile.json';
        }
        return sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'rx_host_profile_' . md5((string) $root) . '.json';
    }
}

if (!function_exists('rx_exec_disabled')) {
    function rx_exec_disabled()
    {
        foreach (['exec', 'shell_exec'] as $fn) {
            if (!function_exists($fn)) {
                return true;
            }
        }
        $disabled = strtolower((string) ini_get('disable_functions'));
        if ($disabled === '') {
            return false;
        }
        foreach (['exec', 'shell_exec'] as $fn) {
            if (preg_match('/(^|,)\s*' . $fn . '\s*(,|$)/', $disabled)) {
                return true;
            }
        }
        return false;
    }
}

if (!function_exists('rx_putenv_disabled')) {
    function rx_putenv_disabled()
    {
        if (!function_exists('putenv')) {
            return true;
        }
        $disabled = strtolower((string) ini_get('disable_functions'));
        if ($disabled === '') {
            return false;
        }
        return (bool) preg_match('/(^|,)\s*putenv\s*(,|$)/', $disabled);
    }
}

if (!function_exists('rx_mysql_show_value')) {
    function rx_mysql_show_value($pdo, $kind, $name)
    {
        try {
            if (!($pdo instanceof PDO)) {
                return 0;
            }
            $kind = ($kind === 'STATUS') ? 'STATUS' : 'VARIABLES';
            $name = preg_replace('/[^A-Za-z0-9_]/', '', (string) $name);
            if ($name === '') {
                return 0;
            }
            $stmt = $pdo->query("SHOW {$kind} LIKE '{$name}'");
            if ($stmt === false) {
                return 0;
            }
            $row = $stmt->fetch(PDO::FETCH_NUM);
            return (is_array($row) && isset($row[1])) ? $row[1] : 0;
        } catch (\Throwable $e) {
            return 0;
        }
    }
}

if (!function_exists('rx_resize_for_profile')) {
    function rx_resize_for_profile($maxConnections, $profile)
    {
