const BLUPAL_RIAL_PER_TOMAN = 10;

function blupalCurlJson($method, $endpoint, array $payload, $apiKey)
{
    $headers = ['Content-Type: application/json'];
    if ($apiKey !== null) {
        $headers[] = 'X-API-Key: ' . $apiKey;
    }

    $curl = curl_init();
    $opts = array(
        CURLOPT_URL => $endpoint,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_ENCODING => '',
        CURLOPT_MAXREDIRS => 5,
        CURLOPT_CONNECTTIMEOUT => 5,
        CURLOPT_TIMEOUT => 8,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        CURLOPT_USERAGENT => 'Faoxima-BluPal-Client/1.0',
        CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $headers,
    );
    if ($method === 'POST') {
        if ($multipart) {
            $opts[CURLOPT_POSTFIELDS] = $payload;
        } else {
            $opts[CURLOPT_POSTFIELDS] = empty($payload) ? '{}' : json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        }
    }
    curl_setopt_array($curl, $opts);

    $response = curl_exec($curl);
    $curlErrno = curl_errno($curl);
    $curlError = curl_error($curl);
    $curlInfo = curl_getinfo($curl);
    $statusCode = $curlInfo['http_code'] ?? null;
    curl_close($curl);

    if ($response === false) {
        error_log('BluPal request failed: ' . json_encode([
            'url' => $endpoint,
            'error' => $curlError,
            'errno' => $curlErrno,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return null;
    }

    $decoded = json_decode($response, true);
    if (!is_array($decoded)) {
        error_log('BluPal invalid response: ' . json_encode([
            'url' => $endpoint,
            'status_code' => $statusCode,
            'raw_response' => $response,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return null;
    }

    $decoded['status_code'] = $statusCode;
    return $decoded;
}

