if (!function_exists('nm_adminInstantReply')) {

function nm_adminInstantReply($chatId, $text, $keyboard = null, $parseMode = 'HTML')
{
    global $message_id, $callback_query_id;

    $alreadyHandled = !empty($message_id)
                      && isset($GLOBALS['rx_admin_instant_deleted'])
                      && $GLOBALS['rx_admin_instant_deleted'] === $message_id;

    $isCallback = !empty($callback_query_id) && !empty($message_id);
    $isInlineKbd = false;
    if (is_string($keyboard) && $keyboard !== '') {
        $decoded = json_decode($keyboard, true);
        if (is_array($decoded) && isset($decoded['inline_keyboard'])) $isInlineKbd = true;
    } elseif (is_array($keyboard) && isset($keyboard['inline_keyboard'])) {
        $isInlineKbd = true;
    }
    if (function_exists('rxNavTrackKeyboard') && (string) $chatId === (string) ($GLOBALS['from_id'] ?? '') && function_exists('rx_isAdminChat') && rx_isAdminChat($chatId)) {
        rxNavTrackKeyboard($chatId, $keyboard);
    }
    $rx_edit_failed = false;

    if ($isCallback && $isInlineKbd && !$alreadyHandled && function_exists('Editmessagetext')) {
        try {
            $rx_edit_result = Editmessagetext($chatId, $message_id, $text, $keyboard, $parseMode);

            if (is_array($rx_edit_result) && !empty($rx_edit_result['ok'])) {

                $GLOBALS['rx_admin_instant_deleted'] = $message_id;

                if (!empty($callback_query_id) && function_exists('telegram')) {
                    try {
                        telegram('answerCallbackQuery', [
                            'callback_query_id' => $callback_query_id,
                            'cache_time' => 1,
                        ]);
                    } catch (Throwable $e) {}
                }
                return true;
            }
            $rx_edit_failed = true;
            if (is_array($rx_edit_result) && isset($rx_edit_result['description'])) {
                $rx_edit_desc = (string) $rx_edit_result['description'];
                $rx_edit_benign = ['message to edit not found','message to delete not found','message is not modified','query is too old','MESSAGE_ID_INVALID'];
                $rx_edit_skip_log = false;
                foreach ($rx_edit_benign as $rx_edit_n) {
                    if (stripos($rx_edit_desc, $rx_edit_n) !== false) { $rx_edit_skip_log = true; break; }
                }
                if (!$rx_edit_skip_log) {
                    error_log('nm_adminInstantReply Editmessagetext not ok: ' . $rx_edit_desc);
                }
            }
        } catch (Throwable $e) {
            $rx_edit_failed = true;
            error_log('nm_adminInstantReply Editmessagetext failed: ' . $e->getMessage());
        }
    }

    if ($rx_edit_failed) {
        if (!empty($callback_query_id) && function_exists('telegram')) {
            try {
                telegram('answerCallbackQuery', [
                    'callback_query_id' => $callback_query_id,
                    'cache_time' => 1,
                ]);
            } catch (Throwable $e) {}
        }
        return sendmessage($chatId, $text, $keyboard, $parseMode);
    }

    if ($isCallback) {
        if (!empty($message_id) && !$alreadyHandled && function_exists('deletemessage')) {
            try { @deletemessage($chatId, $message_id); } catch (Throwable $e) {}
            $GLOBALS['rx_admin_instant_deleted'] = $message_id;
        }
        if (!empty($callback_query_id) && function_exists('telegram')) {
            try {
                telegram('answerCallbackQuery', [
                    'callback_query_id' => $callback_query_id,
                    'cache_time' => 1,
                ]);
            } catch (Throwable $e) {}
        }
        return sendmessage($chatId, $text, $keyboard, $parseMode);
    }

    return sendmessage($chatId, $text, $keyboard, $parseMode);
}}

if (!function_exists('rx_replyGroupIdCommand')) {

function rx_replyGroupIdCommand($update, $from_id, $Chat_type)
{
    global $textbotlang, $datatextbot;
    if ($Chat_type !== 'supergroup') return false;
    if (!isset($update['message']) || !is_array($update['message'])) return false;

    $rxText = (string) ($update['message']['text'] ?? '');
    $rxCmd = trim($rxText);
    $rxAtPos = strpos($rxCmd, '@');
    if ($rxAtPos !== false) $rxCmd = substr($rxCmd, 0, $rxAtPos);
    $rxCmd = mb_strtolower($rxCmd);

    $rxTriggers = ['آیدی', 'ایدی', '/getid', '/getgroupid'];
    if (!in_array($rxCmd, $rxTriggers, true)) return false;

    $chat = $update['message']['chat'] ?? [];
    $rxChatId = isset($chat['id']) ? (string) $chat['id'] : '';
    if ($rxChatId === '' || $rxChatId === '0') return true;
    $rxThreadId = $update['message']['message_thread_id'] ?? null;

    $rxIsBotAdmin = function_exists('rx_isAdminChat') && rx_isAdminChat($from_id);
    if (!$rxIsBotAdmin) {
        $rxSenderStatus = telegram('getChatMember', [
            'chat_id' => $rxChatId,
            'user_id' => $from_id,
        ]);
        $rxSenderRole = $rxSenderStatus['result']['status'] ?? '';
        if (!in_array($rxSenderRole, ['creator', 'administrator'], true)) {
            return true;
        }
    }

    $rxIsForum = !empty($chat['is_forum']);
    if (!$rxIsForum) {
        $rxPayload = [
            'chat_id' => $rxChatId,
            'text' => $datatextbot['dyn_group_setup_topic_not_active'] ?? "⚠️ تاپیک گروه فعال نیست\n\nلطفاً ابتدا از بخش تنظیمات گروه، گزینه تاپیک را فعال کنید؛ سپس مجدداً عبارت «آیدی» یا «ایدی» را داخل گروه ارسال نمایید.",
        ];
        if ($rxThreadId) $rxPayload['message_thread_id'] = $rxThreadId;
        telegram('sendmessage', $rxPayload);
        return true;
    }

    global $APIKEY;
    $rxBotUserId = (int) explode(':', (string) $APIKEY)[0];
    $rxBotMember = $rxBotUserId > 0 ? telegram('getChatMember', [
        'chat_id' => $rxChatId,
        'user_id' => $rxBotUserId,
    ]) : null;
    $rxBotRole = $rxBotMember['result']['status'] ?? '';
    if (!in_array($rxBotRole, ['creator', 'administrator'], true)) {
        $rxPayload = [
            'chat_id' => $rxChatId,
            'text' => $datatextbot['dyn_group_setup_insufficient_access'] ?? "⚠️ دسترسی ربات کافی نیست\n\nلطفاً ابتدا ربات را در این گروه ادمین کنید و دسترسی‌های موردنیاز را در اختیار آن قرار دهید؛ سپس دوباره عبارت «آیدی» یا «ایدی» را ارسال نمایید.",
        ];
        if ($rxThreadId) $rxPayload['message_thread_id'] = $rxThreadId;
        telegram('sendmessage', $rxPayload);
        return true;
    }

    $rxPayload = [
        'chat_id' => $rxChatId,
        'text' => sprintf($datatextbot['dyn_group_setup_chat_id_received'] ?? "✅ آیدی عددی گروه با موفقیت دریافت شد\n\nآیدی عددی این گروه:\n%s\n\nلطفاً این شناسه را کپی کرده و در بخش تنظیم گروه گزارشات ربات ارسال نمایید. 📋", $rxChatId),
        'reply_markup' => json_encode([
            'inline_keyboard' => [
                [['text' => '📋 کپی آیدی گروه', 'copy_text' => ['text' => $rxChatId]]],
            ],
        ]),
    ];
    if ($rxThreadId) $rxPayload['message_thread_id'] = $rxThreadId;
    telegram('sendmessage', $rxPayload);
    return true;
}}

if (!function_exists('nmBuildFindInSetClause')) {
function nmBuildFindInSetClause(string $column, array $candidates, string $paramPrefix): array
{
    $candidates = array_values(array_unique(array_filter(array_map('strval', $candidates), function ($v) {
        return trim($v) !== '';
    })));
    if (!$candidates) {
        return ['', []];
    }
    $parts = [];
    $params = [];
    foreach ($candidates as $i => $value) {
        $key = ":{$paramPrefix}{$i}";
        $parts[] = "FIND_IN_SET({$key}, {$column}) > 0";
        $params[$key] = $value;
    }
    return ['(' . implode(' OR ', $parts) . ')', $params];
}
}

if (!function_exists('nmProductCategoryList')) {
function nmProductCategoryList(array $product): array
{
    $raw = (string) ($product['category'] ?? '');
    return array_values(array_filter(array_map('trim', explode(',', $raw)), function ($v) {
        return $v !== '';
    }));
}
}

if (!function_exists('rxLocationCsvReplaceToken')) {
function rxLocationCsvReplaceToken(string $csv, string $oldName, ?string $newName, ?callable $equals = null): string
{
    $tokens = [];
    foreach (explode(',', $csv) as $token) {
        $bare = trim($token);
        if ($bare === $oldName || ($equals !== null && $bare !== '' && $equals($bare, $oldName))) {
            if ($newName === null) {
                continue;
            }
            $token = $newName;
        }
        if (!in_array($token, $tokens, true)) {
            $tokens[] = $token;
        }
    }
    return implode(',', $tokens);
}
}

if (!function_exists('rxPanelNameCascade')) {
function rxPanelNameCascade(PDO $pdo, string $oldName, ?string $newName): bool
{
    if ($oldName === '' || $oldName === '/all' || $newName === '' || $newName === '/all') {
        return false;
    }
    $run = function (string $sql, array $params) use ($pdo) {
        $stmt = $pdo->prepare($sql);
        if ($stmt === false || $stmt->execute($params) === false) {
            throw new RuntimeException('panel cascade query failed: ' . $sql);
        }
        return $stmt;
    };
    $optionalRefs = [];
    if ($newName !== null) {
        foreach ([['remnawave_users', 'name_panel'], ['queued_renewal', 'name_panel'], ['sale_ledger', 'Service_location']] as $ref) {
            try {
                $exists = $pdo->prepare("SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ? LIMIT 1");
                $exists->execute([$ref[0], $ref[1]]);
                if ($exists->fetchColumn() !== false) {
                    $optionalRefs[] = $ref;
                }
            } catch (Throwable $e) {
                error_log('[rxPanelNameCascade] ' . $e->getMessage());
            }
        }
    }
    $equals = null;
    try {
        $collStmt = $pdo->prepare("SELECT COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marzban_panel' AND COLUMN_NAME = 'name_panel' LIMIT 1");
        $collStmt->execute();
        $collation = (string) $collStmt->fetchColumn();
        if (preg_match('/^utf8mb4_[a-z0-9_]+$/', $collation)) {
            $eqStmt = $pdo->prepare("SELECT CONVERT(? USING utf8mb4) COLLATE {$collation} = CONVERT(? USING utf8mb4) COLLATE {$collation}");
            $equals = function (string $a, string $b) use ($eqStmt) {
                try {
                    $eqStmt->execute([$a, $b]);
                    $result = (int) $eqStmt->fetchColumn();
                    $eqStmt->closeCursor();
                    return $result === 1;
                } catch (Throwable $e) {
                    return false;
                }
            };
        }
    } catch (Throwable $e) {
        error_log('[rxPanelNameCascade] ' . $e->getMessage());
    }
    $hasBotsazHide = rxTableColumnPresent($pdo, 'botsaz', 'hide_panel');
    $ownsTransaction = !$pdo->inTransaction();
    try {
        if ($ownsTransaction) {
            $pdo->beginTransaction();
        }
        if ($hasBotsazHide) {
            $bots = $run("SELECT id_user, hide_panel FROM botsaz FOR UPDATE", [])->fetchAll(PDO::FETCH_ASSOC);
            foreach ($bots as $bot) {
                $list = json_decode((string) $bot['hide_panel'], true);
                if (!is_array($list) || !$list) {
                    continue;
                }
                $nextList = [];
                $changed = false;
                foreach ($list as $item) {
                    if (is_string($item) && (trim($item) === $oldName || ($equals !== null && trim($item) !== '' && $equals(trim($item), $oldName)))) {
                        $changed = true;
                        if ($newName === null) {
                            continue;
                        }
                        $item = $newName;
                    }
                    if (!in_array($item, $nextList, true)) {
                        $nextList[] = $item;
                    }
                }
                if ($changed) {
                    $run("UPDATE botsaz SET hide_panel = ? WHERE id_user = ?", [json_encode(array_values($nextList)), $bot['id_user']]);
                }
            }
        }
        if ($newName === null) {
            $run("DELETE FROM marzban_panel WHERE name_panel = ?", [$oldName]);
        } else {
            $run("UPDATE marzban_panel SET name_panel = ? WHERE name_panel = ?", [$newName, $oldName]);
            $run("UPDATE invoice SET Service_location = ? WHERE Service_location = ?", [$newName, $oldName]);
            foreach ($optionalRefs as $ref) {
                $run("UPDATE `{$ref[0]}` SET `{$ref[1]}` = ? WHERE `{$ref[1]}` = ?", [$newName, $oldName]);
            }
        }
        $like = '%' . addcslashes($oldName, '%_\\') . '%';
        $rows = $run("SELECT id, Location FROM product WHERE Location LIKE ? OR FIND_IN_SET(?, Location) > 0 FOR UPDATE", [$like, $oldName])->fetchAll(PDO::FETCH_ASSOC);
        foreach ($rows as $row) {
            $current = (string) $row['Location'];
            $next = rxLocationCsvReplaceToken($current, $oldName, $newName, $equals);
            if ($next === $current || $next === '') {
                continue;
            }
            $run("UPDATE product SET Location = ? WHERE id = ?", [$next, $row['id']]);
        }
        if ($ownsTransaction) {
            $pdo->commit();
        }
    } catch (Throwable $e) {
        if ($ownsTransaction && $pdo->inTransaction()) {
            $pdo->rollBack();
        }
        error_log('[rxPanelNameCascade] ' . $e->getMessage());
        return false;
    }
    $touched = ['marzban_panel', 'product'];
    if ($hasBotsazHide) {
        $touched[] = 'botsaz';
    }
    if ($newName !== null) {
        $touched[] = 'invoice';
        foreach ($optionalRefs as $ref) {
            $touched[] = $ref[0];
        }
    }
    foreach ($touched as $table) {
        if (function_exists('clearSelectCache')) {
            clearSelectCache($table);
        }
        if (function_exists('faoxima_bust_bot_selectcache')) {
            faoxima_bust_bot_selectcache($table);
        }
    }
    return true;
}
}

if (!function_exists('rxTableColumnPresent')) {
function rxTableColumnPresent(PDO $pdo, string $table, string $column): bool
{
    try {
        $stmt = $pdo->prepare("SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ? LIMIT 1");
        $stmt->execute([$table, $column]);
        return $stmt->fetchColumn() !== false;
    } catch (Throwable $e) {
        error_log('[rxTableColumnPresent] ' . $e->getMessage());
        return false;
    }
}
}

if (!function_exists('rxCategoryRenameCascade')) {
function rxCategoryRenameCascade(PDO $pdo, string $oldName, string $newName): bool
{
    $newName = trim($newName);
    if ($oldName === '' || $newName === '' || $oldName === $newName || $oldName === 'all' || $newName === 'all' || strpos($newName, ',') !== false) {
        return false;
    }
    $run = function (string $sql, array $params) use ($pdo) {
        $stmt = $pdo->prepare($sql);
        if ($stmt === false || $stmt->execute($params) === false) {
            throw new RuntimeException('category cascade query failed: ' . $sql);
        }
        return $stmt;
    };
    $equals = 'rxCategoryNameEquals';
    $hasDiscountCategory = rxTableColumnPresent($pdo, 'DiscountSell', 'code_category');
    $ownsTransaction = !$pdo->inTransaction();
    try {
        if ($ownsTransaction) {
            $pdo->beginTransaction();
        }
        foreach ($run("SELECT remark FROM category WHERE remark <> ? FOR UPDATE", [$oldName])->fetchAll(PDO::FETCH_COLUMN) as $existingRemark) {
            if ($equals((string) $existingRemark, $newName)) {
                throw new RuntimeException('category name already exists: ' . $newName);
            }
        }
        if ($run("UPDATE category SET remark = ? WHERE remark = ?", [$newName, $oldName])->rowCount() < 1) {
            throw new RuntimeException('category not found: ' . $oldName);
        }
        $targets = [['product', 'id', 'category']];
        if ($hasDiscountCategory) {
            $targets[] = ['DiscountSell', 'id', 'code_category'];
        }
        foreach ($targets as [$table, $key, $column]) {
            $rows = $run("SELECT `{$key}` AS k, `{$column}` AS v FROM `{$table}` WHERE `{$column}` IS NOT NULL AND `{$column}` <> '' FOR UPDATE", [])->fetchAll(PDO::FETCH_ASSOC);
            foreach ($rows as $row) {
                $current = (string) $row['v'];
                $next = rxLocationCsvReplaceToken($current, $oldName, $newName, $equals);
                if ($next === $current || $next === '') {
                    continue;
                }
                $run("UPDATE `{$table}` SET `{$column}` = ? WHERE `{$key}` = ?", [$next, $row['k']]);
            }
        }
        if ($ownsTransaction) {
            $pdo->commit();
        }
    } catch (Throwable $e) {
        if ($ownsTransaction && $pdo->inTransaction()) {
            $pdo->rollBack();
        }
        error_log('[rxCategoryRenameCascade] ' . $e->getMessage());
        return false;
    }
    foreach (['category', 'product', 'DiscountSell'] as $table) {
        if (function_exists('clearSelectCache')) {
            clearSelectCache($table);
        }
        if (function_exists('faoxima_bust_bot_selectcache')) {
            faoxima_bust_bot_selectcache($table);
        }
    }
    return true;
}
}

if (!function_exists('rxCategoryNameEquals')) {
function rxCategoryNameEquals(string $a, string $b): bool
{
    if (function_exists('nmNormalizeText')) {
        return nmNormalizeText($a) === nmNormalizeText($b);
    }
    return trim($a) === trim($b);
}
}

if (!function_exists('rxCategoryDeleteGuarded')) {
function rxCategoryDeleteGuarded(PDO $pdo, string $name, ?int $id = null): bool
{
    if (trim($name) === '') {
        return false;
    }
    $run = function (string $sql, array $params) use ($pdo) {
        $stmt = $pdo->prepare($sql);
        if ($stmt === false || $stmt->execute($params) === false) {
            throw new RuntimeException('category delete query failed: ' . $sql);
        }
        return $stmt;
    };
    $ownsTransaction = !$pdo->inTransaction();
    try {
        if ($ownsTransaction) {
            $pdo->beginTransaction();
        }
        $ids = $id !== null
            ? $run("SELECT id FROM category WHERE id = ? AND remark = ? FOR UPDATE", [$id, $name])->fetchAll(PDO::FETCH_COLUMN)
            : $run("SELECT id FROM category WHERE remark = ? FOR UPDATE", [$name])->fetchAll(PDO::FETCH_COLUMN);
        if (!$ids) {
            throw new RuntimeException('category not found: ' . $name);
        }
        $idTokens = array_map('strval', $ids);
        $productCategories = $run("SELECT category FROM product WHERE category IS NOT NULL AND category <> '' LOCK IN SHARE MODE", [])->fetchAll(PDO::FETCH_COLUMN);
        foreach ($productCategories as $csv) {
            foreach (explode(',', (string) $csv) as $token) {
                $token = trim($token);
                if ($token !== '' && (rxCategoryNameEquals($token, $name) || in_array($token, $idTokens, true))) {
                    throw new RuntimeException('category has dependent products: ' . $name);
                }
            }
        }
        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $run("DELETE FROM category WHERE id IN ({$placeholders})", $ids);
        if ($ownsTransaction) {
            $pdo->commit();
        }
    } catch (Throwable $e) {
        if ($ownsTransaction && $pdo->inTransaction()) {
            $pdo->rollBack();
        }
        error_log('[rxCategoryDeleteGuarded] ' . $e->getMessage());
        return false;
    }
    if (function_exists('clearSelectCache')) {
        clearSelectCache('category');
    }
    if (function_exists('faoxima_bust_bot_selectcache')) {
        faoxima_bust_bot_selectcache('category');
    }
    return true;
}
}


if (!function_exists('nmSellableCategoryRows')) {
function nmSellableCategoryRows($location, $agent)
{
    global $pdo;
    $out = [];
    if (!($pdo instanceof PDO)) return $out;
    $norm = static function ($v) {
        return function_exists('nmNormalizeText') ? nmNormalizeText($v) : trim((string)$v);
    };
    // 1) Collect the (normalised) category tokens that products for this panel use.
    $prodSet = [];
    try {
        $stmt = $pdo->prepare(
            "SELECT category FROM product "
            . "WHERE (FIND_IN_SET(:loc, Location) > 0 OR Location = '/all') "
            . "AND (FIND_IN_SET(:agent, REPLACE(agent, ' ', '')) > 0 OR agent IN ('all', 'allusers')) "
            . "AND category IS NOT NULL AND TRIM(category) <> ''"
        );
        $stmt->execute([':loc' => $location, ':agent' => $agent]);
        foreach (($stmt->fetchAll(PDO::FETCH_COLUMN) ?: []) as $pc) {
            foreach (explode(',', (string) $pc) as $piece) {
                $n = $norm($piece);
                if ($n !== '' && $n !== '0') $prodSet[$n] = true;
            }
        }
    } catch (Throwable $e) {
        error_log('nmSellableCategoryRows products failed: ' . $e->getMessage());
        return $out;
    }
    if (!$prodSet) return $out;
    // 2) Keep the category rows whose remark/id/name/title matches a product token.
    try {
        $stmt = $pdo->query("SELECT * FROM category ORDER BY (position = 0) ASC, position ASC, id ASC");
        while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
            foreach (['remark', 'id', 'name', 'title'] as $k) {
                if (!isset($row[$k]) || trim((string)$row[$k]) === '') continue;
                if (isset($prodSet[$norm($row[$k])])) { $out[] = $row; break; }
            }
        }
    } catch (Throwable $e) {
        error_log('nmSellableCategoryRows categories failed: ' . $e->getMessage());
    }
    return $out;
}
}

function nmHasSellableCategories($location, $agent)
{
    return count(nmSellableCategoryRows($location, $agent)) > 0;
}

function nmDecodeState($raw)
{
    if (is_array($raw)) return $raw;
    $decoded = json_decode((string)$raw, true);
    return is_array($decoded) ? $decoded : [];
}

function nmResolvePanelFromUserState(array $user = null, $fallbackPanelName = null)
{
    $candidates = [];
    if ($user) {
        foreach (['Processing_value', 'Processing_value_one', 'Processing_value_tow', 'Processing_value_four'] as $stateField) {
            if (!array_key_exists($stateField, $user)) {
                continue;
            }
            $state = nmDecodeState($user[$stateField] ?? '');
            foreach (['namepanel', 'name_panel', 'panel', 'panel_name', 'code_panel', 'codepanel', 'stock_codepanel', 'source_codepanel'] as $key) {
                if (!empty($state[$key])) {
                    $candidates[] = trim((string)$state[$key]);
                }
            }

            if (!is_array($user[$stateField])) {
                $raw = trim((string)$user[$stateField]);
                if ($raw !== '' && $raw !== '0' && $raw !== 'none' && $raw[0] !== '{' && $raw[0] !== '[') {
                    $candidates[] = $raw;
                }
            }
        }
    }
    if ($fallbackPanelName !== null && trim((string)$fallbackPanelName) !== '') {
        $candidates[] = trim((string)$fallbackPanelName);
    }
    foreach (array_unique(array_filter($candidates)) as $candidate) {
        try {
            $panel = select('marzban_panel', '*', 'name_panel', $candidate, 'select');
            if ($panel) return $panel;
            $panel = select('marzban_panel', '*', 'code_panel', $candidate, 'select');
            if ($panel) return $panel;
            if (ctype_digit((string)$candidate)) {
                $panel = select('marzban_panel', '*', 'id', $candidate, 'select');
                if ($panel) return $panel;
            }
        } catch (Throwable $e) {}
    }
    return false;
}

function nmResolvePanelNameForUser(array $user = null, $fallback = null)
{
    if ($user) {
        foreach (['Processing_value', 'Processing_value_one', 'Processing_value_tow', 'Processing_value_four'] as $stateField) {
            if (!array_key_exists($stateField, $user)) continue;
            $raw = $user[$stateField];
            if (is_string($raw)) {
                $trim = trim($raw);
                if ($trim !== '' && $trim[0] !== '{' && $trim[0] !== '[' && $trim !== '0' && $trim !== 'none') {
                    return $trim;
                }
                $state = nmDecodeState($trim);
                foreach (['namepanel', 'name_panel', 'panel', 'panel_name'] as $key) {
                    if (!empty($state[$key])) return trim((string)$state[$key]);
                }
            } elseif (is_array($raw)) {
                foreach (['namepanel', 'name_panel', 'panel', 'panel_name'] as $key) {
                    if (!empty($raw[$key])) return trim((string)$raw[$key]);
                }
            }
        }
    }
    if ($fallback !== null) {
        $fallback = trim((string)$fallback);
        if ($fallback !== '') return $fallback;
    }
    $resolved = nmResolvePanelFromUserState($user, $fallback);
    if (is_array($resolved) && !empty($resolved['name_panel'])) return (string)$resolved['name_panel'];
    return '';
}


function nmNormalizeText($value)
{
    $value = trim((string)$value);
    $value = preg_replace('/[\x{200c}\x{200d}\x{200e}\x{200f}\x{202a}-\x{202e}]/u', '', $value);
    $value = str_replace(["ي", "ك", "ة", "ۀ"], ["ی", "ک", "ه", "ه"], $value);
    $value = preg_replace('/\s+/u', ' ', $value);
    return trim($value);
}

function nmProductButtonName($text)
{
    $text = nmNormalizeText($text);
    $text = preg_replace('/\s*-\s*[0-9۰-۹,،.]+\s*(?:تومان|ریال)?\s*$/u', '', $text);
    return nmNormalizeText($text);
}

function nmTableHasColumn($table, $column)
{
    global $pdo;
    try {
        $stmt = $pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :t AND COLUMN_NAME = :c");
        $stmt->execute([':t' => $table, ':c' => $column]);
        return ((int)$stmt->fetchColumn()) > 0;
    } catch (Throwable $e) { return false; }
}

function nmCategoryLookupValues($category)
{
    $values = [];
    $category = nmNormalizeText($category);
    if ($category === '' || $category === 'بدون دسته‌بندی') {
        return [];
    }

    $values[] = $category;
    $lookupColumns = [];
    foreach (['id', 'remark', 'name', 'title'] as $column) {
        if (function_exists('nmTableHasColumn') && nmTableHasColumn('category', $column)) {
            $lookupColumns[] = $column;
        }
    }

    foreach ($lookupColumns as $column) {
        if ($column === 'id' && !ctype_digit((string)$category)) {
            continue;
        }
        try {
            $row = select('category', '*', $column, $category, 'select');
            if (is_array($row) && $row) {
                foreach (['id', 'remark', 'name', 'title'] as $k) {
                    if (array_key_exists($k, $row) && trim((string)$row[$k]) !== '') {
                        $values[] = nmNormalizeText($row[$k]);
                    }
                }
            }
        } catch (Throwable $e) {
            error_log('nmCategoryLookupValues lookup failed on category.' . $column . ': ' . $e->getMessage());
        }
    }

    if (in_array('remark', $lookupColumns, true) && in_array('id', $lookupColumns, true)) {
        try {
            $row = select('category', '*', 'remark', $category, 'select');
            if (is_array($row) && isset($row['id'])) {
                $values[] = nmNormalizeText($row['id']);
            }
        } catch (Throwable $e) {}
    }

    return array_values(array_unique(array_filter($values, static function($v) { return trim((string)$v) !== ''; })));
}
function nmProductsForPanelCategory(array $panel, $agent = 'all', $category = null)
{
    global $pdo;
    $loc = trim((string)($panel['name_panel'] ?? ''));
    if ($loc === '' || !isset($pdo)) return [];

    $agent = trim((string)($agent ?? ''));
    $filterAgent = !in_array($agent, ['', 'all', '*', 'any'], true);
    $params = [
        ':loc_where' => $loc,
        ':loc_order' => $loc,
    ];
    $sql = "SELECT * FROM product WHERE (FIND_IN_SET(:loc_where, Location) > 0 OR Location = '/all')";
    if ($filterAgent) {
        $sql .= " AND (FIND_IN_SET(:agent, REPLACE(agent, ' ', '')) > 0 OR agent IN ('all', 'allusers'))";
        $params[':agent'] = $agent;
    }

    $catValues = nmCategoryLookupValues($category);
    if ($catValues) {
        [$catSql, $catParams] = nmBuildFindInSetClause('category', $catValues, 'cat');
        if ($catSql !== '') {
            $sql .= " AND ({$catSql}";
            $params += $catParams;
            if (nmTableHasColumn('product', 'category_id')) {
                $inId = [];
                foreach ($catValues as $j => $value) {
                    $key = ':cat_id' . $j;
                    $inId[] = $key;
                    $params[$key] = $value;
                }
                $sql .= ' OR category_id IN (' . implode(',', $inId) . ')';
            }
            $sql .= ')';
        }
    }
    $sql .= " ORDER BY CASE WHEN FIND_IN_SET(:loc_order, Location) > 0 THEN 0 ELSE 1 END, CAST(price_product AS UNSIGNED) ASC, id DESC";
    try {
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];
        if (!$rows && $catValues) {
            $fallbackParams = [
                ':fallback_loc_where' => $loc,
                ':fallback_loc_order' => $loc,
            ];
            $fallbackSql = "SELECT * FROM product WHERE (FIND_IN_SET(:fallback_loc_where, Location) > 0 OR Location = '/all')";
            if ($filterAgent) {
                $fallbackSql .= " AND (FIND_IN_SET(:agent, REPLACE(agent, ' ', '')) > 0 OR agent IN ('all', 'allusers'))";
                $fallbackParams[':agent'] = $agent;
            }
            $fallbackSql .= " ORDER BY CASE WHEN FIND_IN_SET(:fallback_loc_order, Location) > 0 THEN 0 ELSE 1 END, CAST(price_product AS UNSIGNED) ASC, id DESC";
            $stmt = $pdo->prepare($fallbackSql);
            $stmt->execute($fallbackParams);
            $rows = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];
        }
        return $rows;
    } catch (Throwable $e) {
        error_log('nmProductsForPanelCategory failed: ' . $e->getMessage());
        return [];
    }
}

function nmProductByCodeForPanel($codeProduct, $panelName, $agent = null)
{
    global $pdo;

    $codeProduct = trim((string) $codeProduct);
    $panelName = trim((string) $panelName);
    $agent = $agent === null ? null : trim((string) $agent);

    if (!($pdo instanceof PDO) || $codeProduct === '' || $panelName === '') {
        return false;
    }

    try {
        $sql = "SELECT * FROM product
                WHERE code_product = :code_product
                  AND (FIND_IN_SET(:location_where, Location) > 0 OR Location = '/all')";
        $params = [
            ':code_product' => $codeProduct,
            ':location_where' => $panelName,
            ':location_order' => $panelName,
        ];

        if ($agent !== null && $agent !== '') {
            $sql .= " AND (FIND_IN_SET(:agent_where, REPLACE(agent, ' ', '')) > 0 OR agent IN ('all', 'allusers'))";
            $params[':agent_where'] = $agent;
            $params[':agent_order'] = $agent;
            $sql .= " ORDER BY
                        CASE WHEN FIND_IN_SET(:location_order, Location) > 0 THEN 0 ELSE 1 END,
                        CASE WHEN agent = :agent_order THEN 0 WHEN agent = 'all' THEN 1 ELSE 2 END,
                        id ASC
                      LIMIT 1";
        } else {
            $sql .= " ORDER BY CASE WHEN FIND_IN_SET(:location_order, Location) > 0 THEN 0 ELSE 1 END, id ASC LIMIT 1";
        }

        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return $row ?: false;
    } catch (Throwable $e) {
        error_log('nmProductByCodeForPanel failed: ' . $e->getMessage());
        return false;
    }
}

function nmProductByNameForPanel($productName, $panelName, $agent = null, $category = null)
{
    global $pdo;
    try {
        $productName = nmProductButtonName($productName);
        $panelName = trim((string)$panelName);
        $params = [
            ':name_product' => $productName,
            ':location_where' => $panelName,
            ':location_order' => $panelName,
        ];
        $sql = "SELECT * FROM product WHERE name_product = :name_product AND (FIND_IN_SET(:location_where, Location) > 0 OR Location = '/all')";
        $catValues = nmCategoryLookupValues($category);
        if ($catValues) {
            [$catSql, $catParams] = nmBuildFindInSetClause('category', $catValues, 'cat');
            if ($catSql !== '') {
                $sql .= " AND ({$catSql}";
                $params += $catParams;
                if (nmTableHasColumn('product', 'category_id')) {
                    $inId = [];
                    foreach ($catValues as $j => $value) {
                        $key = ':cat_id' . $j;
                        $inId[] = $key;
                        $params[$key] = $value;
                    }
                    $sql .= ' OR category_id IN (' . implode(',', $inId) . ')';
                }
                $sql .= ')';
            }
        }
        $agent = trim((string)($agent ?? ''));
        if (!in_array($agent, ['', 'all', '*', 'any'], true)) {
            $sql .= " AND (FIND_IN_SET(:agent, REPLACE(agent, ' ', '')) > 0 OR agent IN ('all', 'allusers'))";
            $params[':agent'] = $agent;
        }
        $sql .= " ORDER BY CASE WHEN FIND_IN_SET(:location_order, Location) > 0 THEN 0 ELSE 1 END LIMIT 1";
        $stmt = $pdo->prepare($sql); $stmt->execute($params); $row = $stmt->fetch(PDO::FETCH_ASSOC); if ($row) return $row;

        $rows = nmProductsForPanelCategory(['name_panel' => $panelName], $agent ?: 'all', $category);
        foreach ($rows as $r) if (nmNormalizeText($r['name_product'] ?? '') === $productName) return $r;
        foreach ($rows as $r) { $name = nmNormalizeText($r['name_product'] ?? ''); if ($name !== '' && (mb_strpos($productName, $name) !== false || mb_strpos($name, $productName) !== false)) return $r; }
        if (count($rows) === 1) return $rows[0];
        return false;
    } catch (Throwable $e) {
        error_log('nmProductByNameForPanel failed: ' . $e->getMessage());
        return false;
    }
}

function nm_renderInfoCardForInvoice($panel_info, $username_service, $invoice_id, $user_id)
{
    if (!function_exists('createServiceInfoCard')) {
        return null;
    }
    if (!function_exists('getInfoCardStatus') || !getInfoCardStatus()) {
        return null;
    }
    if (is_array($panel_info) && ($panel_info['type'] ?? '') === 'Manualsale') {
        return null;
    }
    if (is_array($panel_info) && function_exists('nmPanelNationalEnabled') && nmPanelNationalEnabled($panel_info)) {
        return null;
    }
    global $ManagePanel, $setting;
    try {
        if (!isset($ManagePanel) || !is_object($ManagePanel) || !method_exists($ManagePanel, 'DataUser')) {
            return null;
        }
        $name_panel = is_array($panel_info) ? ($panel_info['name_panel'] ?? '') : '';
        if ($name_panel === '') {
            return null;
        }
        $data = @$ManagePanel->DataUser($name_panel, $username_service);
        if (!is_array($data) || (isset($data['status']) && $data['status'] === 'Unsuccessful')) {
            return null;
        }
        $used  = (float)($data['used_traffic'] ?? 0);
        $total = (float)($data['data_limit']   ?? 0);
        $expire = $data['expire'] ?? 0;
        $unlimitedTime = empty($expire);
        $daysLeft = 0;
        if (!$unlimitedTime) {
            $diff = (int)$expire - time();
            $daysLeft = max(0, (int) floor($diff / 86400));
        }
        $statusVal = (string)($data['status'] ?? 'active');
        $isActive = in_array($statusVal, ['active', 'on_hold'], true);


        $botUsername = '';
        if (is_array($setting ?? null)) {
            foreach (['bot_username', 'username_bot', 'usernamebot', 'BotUsername', 'bot_user'] as $k) {
                if (isset($setting[$k]) && is_string($setting[$k]) && trim($setting[$k]) !== '') {
                    $botUsername = ltrim((string)$setting[$k], '@');
                    break;
                }
            }
        }
        if ($botUsername === '' && function_exists('telegram')) {
            $me = @telegram('getMe', []);
            if (is_array($me) && isset($me['result']['username'])) {
                $botUsername = (string)$me['result']['username'];
            }
        }

        $color = function_exists('getInfoCardColor') ? getInfoCardColor() : 'yellow';
        $params = [
            'config_name'    => (string)$username_service,
            'bot_username'   => $botUsername,
            'user_id'        => (string)$user_id,
            'active'         => $isActive,
            'used_bytes'     => $used,
            'total_bytes'    => $total,
            'days_left'      => $daysLeft,
            'unlimited_time' => $unlimitedTime,
        ];
        $outPath = (defined('REFACTORED_LEGACY_ROOT') ? REFACTORED_LEGACY_ROOT : __DIR__)
            . DIRECTORY_SEPARATOR . 'infocard_' . $user_id . '_' . bin2hex(random_bytes(3)) . '.png';
        $written = createServiceInfoCard($params, $color, $outPath);
        if ($written === false) {
            return null;
        }
        return $written;
    } catch (\Throwable $e) {
        error_log('nm_renderInfoCardForInvoice failed: ' . $e->getMessage());
        return null;
    }
}

function nm_sendServiceQrFallback($user_id, string $qrPayload, string $backgroundImage = 'images.jpg', string $caption = '', $replyMarkup = null): bool
{
    if (function_exists('isQrDisabled') && isQrDisabled()) {
        return false;
    }
    if (!function_exists('createqrcode') || !function_exists('telegram')) {
        return false;
    }
    $qrPayload = trim($qrPayload);
    if ($qrPayload === '') {
        return false;
    }
    try {
        $qrCode = createqrcode($qrPayload);
        if ($qrCode === null) {
            return false;
        }
        $urlimage = (defined('REFACTORED_LEGACY_ROOT') ? REFACTORED_LEGACY_ROOT : __DIR__)
            . DIRECTORY_SEPARATOR . $user_id . bin2hex(random_bytes(3)) . '.png';
        file_put_contents($urlimage, $qrCode->getString());
        if (function_exists('addBackgroundImage')) {
            @addBackgroundImage($urlimage, $qrCode, $backgroundImage);
        }
        telegram('sendphoto', [
            'chat_id'    => $user_id,
            'photo'      => new CURLFile($urlimage),
            'caption'    => $caption !== '' ? $caption : '📥 کیو‌آر کد',
            'parse_mode' => 'HTML',
            'reply_markup' => $replyMarkup,
        ]);
        @unlink($urlimage);
        return true;
    } catch (Throwable $e) {
        error_log('nm_sendServiceQrFallback failed: ' . $e->getMessage());
        return false;
    }
}

if (!function_exists('rx_cleanEmojiAndSymbols')) {
    function rx_cleanEmojiAndSymbols($str): string {
        $str = (string)$str;
        $str = preg_replace('/[\x{1F000}-\x{1FFFF}\x{2600}-\x{27BF}\x{2300}-\x{23FF}\x{2000}-\x{32FF}\x{FE00}-\x{FE0F}\x{200D}\x{200C}\x{200E}\x{200F}\x{202A}-\x{202E}\x{2066}-\x{2069}]/u', '', $str);
        $str = str_replace(["ي", "ك", "ة", "ۀ"], ["ی", "ک", "ه", "ه"], $str);
        $str = preg_replace('/\s+/u', ' ', $str);
        $str = trim($str);
        return function_exists('mb_strtolower') ? mb_strtolower($str, 'UTF-8') : strtolower($str);
    }
}

if (!function_exists('rx_resolvePanelFromInput')) {
    function rx_resolvePanelFromInput($input, $pdo = null) {
        if (!is_string($input) || trim($input) === '') {
            return null;
        }
        $rawInput = trim($input);
        if ($rawInput === '/all') {
            return ['code_panel' => '/all', 'name_panel' => '/all', 'type' => 'all'];
        }
        if (function_exists('rx_restorePremiumReplyText')) {
            $restored = rx_restorePremiumReplyText($rawInput);
            if ($restored !== '' && $restored !== $rawInput) {
                if (function_exists('select')) {
                    $direct = select("marzban_panel", "*", "name_panel", $restored, "select");
                    if (is_array($direct) && !empty($direct)) {
                        return $direct;
                    }
                }
            }
        }
        if (function_exists('select')) {
            $direct = select("marzban_panel", "*", "name_panel", $rawInput, "select");
            if (is_array($direct) && !empty($direct)) {
                return $direct;
            }
        }
        if ($pdo === null) {
            global $pdo;
        }
        if (!($pdo instanceof PDO)) {
            return null;
        }
        try {
            $stmt = $pdo->prepare("SELECT * FROM marzban_panel WHERE name_panel = ? LIMIT 1");
            $stmt->execute([$rawInput]);
            $row = $stmt->fetch(PDO::FETCH_ASSOC);
            if (is_array($row) && !empty($row)) {
                return $row;
            }
            $stmt = $pdo->query("SELECT * FROM marzban_panel WHERE name_panel IS NOT NULL AND name_panel <> ''");
            $allPanels = $stmt ? $stmt->fetchAll(PDO::FETCH_ASSOC) : [];
            if (!is_array($allPanels) || empty($allPanels)) {
                return null;
            }
            $cleanInput = rx_cleanEmojiAndSymbols($rawInput);
            if ($cleanInput !== '') {
                foreach ($allPanels as $p) {
                    if (!isset($p['name_panel'])) continue;
                    $cleanP = rx_cleanEmojiAndSymbols($p['name_panel']);
                    if ($cleanP === $cleanInput) {
                        return $p;
                    }
                }
                foreach ($allPanels as $p) {
                    if (!isset($p['name_panel'])) continue;
                    $cleanP = rx_cleanEmojiAndSymbols($p['name_panel']);
                    if ($cleanP !== '' && ($cleanP === $cleanInput || strpos($cleanP, $cleanInput) !== false || strpos($cleanInput, $cleanP) !== false)) {
                        return $p;
                    }
                }
            }
        } catch (Throwable $e) {
            return null;
        }
        return null;
    }
}

