if (!function_exists('rxNavCashbackGatewayParent')) {
    function rxNavCashbackGatewayParent($from_id)
    {
        static $map = [
            'CartManage'                  => 'gw_cart',
            'trnado'                      => 'gw_trnado',
            'tonpay'                      => 'gw_tonpay',
            'cubepay'                     => 'gw_cubepay',
            'blupal'                      => 'gw_blupal',
            'abangateway'                 => 'gw_abangateway',
            'atlaspay'                    => 'gw_atlaspay',
            'NowPaymentsManage'           => 'gw_plisio',
            'nowpayment_setting_keyboard' => 'gw_nowpayment',
            'keyboardzarinpal'            => 'gw_zarinpal',
        ];
        $raw = null;
        if (isset($GLOBALS['user']) && is_array($GLOBALS['user']) && isset($GLOBALS['user']['Processing_value'])) {
            $raw = $GLOBALS['user']['Processing_value'];
        } elseif (function_exists('select')) {
            $row = select('user', 'Processing_value', 'id', $from_id, 'select', ['cache' => false]);
            $raw = is_array($row) ? ($row['Processing_value'] ?? null) : null;
        }
        if (!is_string($raw) || $raw === '') {
            return null;
        }
        $data = json_decode($raw, true);
        if (!is_array($data) || !isset($data['cashback_menu']) || !is_string($data['cashback_menu'])) {
            return null;
        }
        return $map[$data['cashback_menu']] ?? null;
    }
}

if (!function_exists('rxNavBack')) {
    function rxNavBack($from_id, $originHint = null, $currentStep = null)
    {
        try {
            $target = null;

            if ($currentStep === null) {
                $row = function_exists('select') ? select('user', 'step', 'id', $from_id, 'select', ['cache' => false]) : null;
                $currentStep = (is_array($row) && isset($row['step'])) ? (string) $row['step'] : '';
            }
            $currentStep = (string) $currentStep;

            $cashbackSharedSteps = ['getcashtarget' => true, 'getcashtargetdays' => true, 'getcashscope' => true];

            if (is_string($originHint) && $originHint !== '') {
                $target = $originHint;
            } elseif (isset($cashbackSharedSteps[$currentStep]) && ($gwParent = rxNavCashbackGatewayParent($from_id)) !== null) {
                $target = $gwParent;
            } elseif (rxNavIsMenuStep($currentStep)) {
                $target = rxNavParent($currentStep);
            } elseif ($currentStep !== '' && $currentStep !== 'home') {
                $parent = rxNavParent($currentStep);
                if ($parent !== null && $parent !== '') {
                    $target = $parent;
                } else {
                    $navState = rxNavGetState($from_id);
                    if (rxIsRenderableState($navState) && $navState !== 'home') {
                        $target = $navState;
                    } else {
                        $target = $parent;
                    }
                }
            } else {
                $target = rxNavParent(rxNavGetState($from_id));
            }

            if ($target === null || $target === '') {
                return false;
            }

            $seen = [];
            while ($target !== null && $target !== '' && !rxIsRenderableState($target)) {
                if (isset($seen[$target])) {
                    return false;
                }
                $seen[$target] = true;
                $target = rxNavParent($target);
            }

            if ($target === null || $target === '' || !rxIsRenderableState($target)) {
                return false;
            }

            return rxRenderMenuState($target, $from_id) ? true : false;
        } catch (\Throwable $e) {
            if (function_exists('rx_log_event')) {
                rx_log_event('NAV_BACK_FAILED', $e->getMessage(), ['from_id' => $from_id, 'origin' => $originHint]);
            }
            return false;
        }
    }
}

if (!function_exists('rxAssertUniqueMenuCallbacks')) {
    function rxAssertUniqueMenuCallbacks(array $keyboardJsons)
    {
        $navExempt = array_flip([
            'backmenu', 'backadmin', 'admin', 'adm_hub_main', 'adm_backmenu', 'backuser',
            'cart_backmenu', 'trnado_backmenu', 'zpal_backmenu', 'zpey_backmenu',
            'aqaye_backmenu', 'plisio_backmenu', 'help_backmenu', 'feat_backmenu',
            'ch_backmenu', 'set_backmenu', 'shop_backmenu', 'cat_back', 'shopitem_back',
            'usershub_backmenu', 'panelshub_backmenu', 'channelhub_backmenu', 'wallet_backmenu',
            'tonpay_backmenu', 'cubepay_backmenu', 'blupal_backmenu', 'variza_backmenu', 'abangateway_backmenu', 'atlaspay_backmenu',
        ]);
        $seen = [];
        $collisions = [];
        $walk = function ($node) use (&$walk, &$seen, &$collisions, $navExempt) {
            if (!is_array($node)) {
                return;
            }
            if (isset($node['callback_data']) && is_string($node['callback_data'])) {
                $cb = $node['callback_data'];
                if (!isset($navExempt[$cb])) {
                    if (isset($seen[$cb])) {
                        $collisions[$cb] = ($collisions[$cb] ?? 1) + 1;
                    }
                    $seen[$cb] = true;
                }
            }
            foreach ($node as $child) {
                if (is_array($child)) {
                    $walk($child);
                }
            }
        };
        foreach ($keyboardJsons as $json) {
            $decoded = is_array($json) ? $json : (is_string($json) && $json !== '' ? json_decode($json, true) : null);
            if (is_array($decoded)) {
                $walk($decoded);
            }
        }
        if (!empty($collisions) && function_exists('rx_log_event')) {
            rx_log_event('NAV_CALLBACK_COLLISION', json_encode($collisions, JSON_UNESCAPED_UNICODE), []);
        }
        return $collisions;
    }
}

if (!function_exists('rx_panel_valid_sale_predicate')) {
    function rx_panel_valid_sale_predicate()
    {
        return "(status = 'active' OR status = 'end_of_time' OR status = 'end_of_volume' OR status = 'sendedwarn' OR Status = 'send_on_hold') AND name_product != 'سرویس تست'";
    }
}

if (!function_exists('panelRealTotalRevenue')) {
    function panelRealTotalRevenue(string $panel): int
    {
        global $connect;
        $predicate = rx_panel_valid_sale_predicate();
        $panelEsc = mysqli_real_escape_string($connect, $panel);
        $invoiceRow = mysqli_fetch_assoc(mysqli_query($connect, "SELECT SUM(price_product) AS s FROM invoice WHERE $predicate AND Service_location = '$panelEsc'"));
        $ledgerRow = mysqli_fetch_assoc(mysqli_query($connect, "SELECT SUM(amount) AS s FROM sale_ledger WHERE Service_location = '$panelEsc'"));
        return (int)($invoiceRow['s'] ?? 0) + (int)($ledgerRow['s'] ?? 0);
    }
}

if (!function_exists('panelDailySalesAverage30d')) {
    function panelDailySalesAverage30d(string $panel): float
    {
        global $connect;
        $predicate = rx_panel_valid_sale_predicate();
        $panelEsc = mysqli_real_escape_string($connect, $panel);
        $since = time() - (30 * 86400);
        $invoiceRow = mysqli_fetch_assoc(mysqli_query($connect, "SELECT COALESCE(SUM(price_product),0) AS s FROM invoice WHERE $predicate AND Service_location = '$panelEsc' AND time_sell >= $since"));
        $ledgerRow = mysqli_fetch_assoc(mysqli_query($connect, "SELECT COALESCE(SUM(amount),0) AS s FROM sale_ledger WHERE Service_location = '$panelEsc' AND created_at >= $since"));
        $total = (float)($invoiceRow['s'] ?? 0) + (float)($ledgerRow['s'] ?? 0);
        return $total / 30;
    }
}

if (!function_exists('panelTopPerformingPlan')) {
