        $hours = (int) ($settings['time_hours'] ?? 0);
        if ($hours <= 0) {
            $hours = RX_TEST_DEFAULT_HOURS;
        }
        $now = $now === null ? time() : (int) $now;
        return $now + ($hours * 3600);
    }
}

