        if ($skip) {
            return null;
        }
        $phonePolicy = (($setting['get_number'] ?? '') === 'onAuthenticationphone') || (($setting['iran_number'] ?? '') === 'onAuthenticationiran');
        if ($phonePolicy && (string) ($user['number'] ?? 'none') === 'none') {
            return 'phone';
        }
        if (!$isAdmin && ($setting['verifystart'] ?? '') === 'onverify' && intval($user['verify'] ?? 0) === 0) {
