        $kb['inline_keyboard'][] = [['text' => '🔎 بررسی تطبیق و اقدامات مالی', 'callback_data' => 'sbv_o_' . $orderId]];
        return json_encode($kb, JSON_UNESCAPED_UNICODE);
    }
}

