                'helpsection_' => 'help', 'helpos_' => 'help',
            ],
            'text' => [
                'text_sell' => 'purchase', 'text_extend' => 'extend', 'text_Purchased_services' => 'services',
                'accountwallet' => 'wallet', 'text_usertest' => 'test', 'text_Tariff_list' => 'tariff',
                'text_affiliates' => 'referral', 'text_wheel_luck' => 'wheel', 'text_help' => 'help',
                'text_support' => 'support', 'textpanelagent' => 'agent', 'textrequestagent' => 'agent',
            ],
        ];
    }
}

if (!function_exists('rx_ui_route_callback')) {
    function rx_ui_route_callback($callback): ?string
    {
        $callback = (string) $callback;
        if ($callback === '') {
            return null;
        }
        $tables = rx_ui_route_tables();
        if (isset($tables['exact'][$callback])) {
            return $tables['exact'][$callback];
        }
        foreach ($tables['prefix'] as $prefix => $section) {
            if (strpos($callback, $prefix) === 0) {
                return $section;
            }
        }
        return null;
    }
}

if (!function_exists('rx_ui_route')) {
    function rx_ui_route($datain, $text): ?string
    {
        $section = rx_ui_route_callback($datain);
        if ($section !== null) {
            return $section;
        }
        $text = trim((string) $text);
        if ($text === '') {
            return null;
        }
        if ($text === '/start' || $text === 'start') {
            return 'main_menu';
        }
        if ($text === '/services') {
            return 'services';
        }
        $backLabel = (string) ($GLOBALS['textbotlang']['users']['backbtn'] ?? '');
        if ($backLabel !== '' && $text === $backLabel) {
            return 'main_menu';
        }
        $datatextbot = $GLOBALS['datatextbot'] ?? [];
        foreach (rx_ui_route_tables()['text'] as $key => $section) {
            if (isset($datatextbot[$key]) && is_string($datatextbot[$key]) && $datatextbot[$key] !== '' && $text === $datatextbot[$key]) {
                return $section;
            }
        }
        return null;
    }
}

if (!function_exists('rx_ui_resolve_request')) {
    function rx_ui_resolve_request(): void
    {
        if (!function_exists('rx_richUserButtonsOn') || !rx_richUserButtonsOn()) {
            return;
        }
        $catalog = rx_ui_section_catalog();
        $user = $GLOBALS['user'] ?? [];
        $persisted = is_array($user) ? (string) ($user['ui_section'] ?? '') : '';
        $route = rx_ui_route($GLOBALS['datain'] ?? '', $GLOBALS['text'] ?? '');
        if ($route !== null) {
            $GLOBALS['rx_ui_section'] = $route;
            if ($route !== $persisted && isset($GLOBALS['from_id'])) {
                try {
                    rx_ui_ensure_user_column();
                    update('user', 'ui_section', $route, 'id', $GLOBALS['from_id']);
                    if (is_array($GLOBALS['user'] ?? null)) {
                        $GLOBALS['user']['ui_section'] = $route;
                    }
                } catch (Throwable $e) {
                    error_log('[ui_sections] persist failed: ' . $e->getMessage());
                }
            }
            return;
        }
        $GLOBALS['rx_ui_section'] = isset($catalog[$persisted]) ? $persisted : 'main_menu';
    }
}

if (!function_exists('rx_ui_ensure_user_column')) {
    function rx_ui_ensure_user_column(): void
    {
        static $done = false;
        if ($done) {
            return;
        }
        $done = true;
        global $pdo;
        try {
            $stmt = $pdo->prepare('SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = ? AND column_name = ?');
            $stmt->execute(['user', 'ui_section']);
            if ((int) $stmt->fetchColumn() === 0) {
                $pdo->exec('ALTER TABLE `user` ADD `ui_section` VARCHAR(24) NULL');
            }
        } catch (Throwable $e) {
            error_log('[ui_sections] user column: ' . $e->getMessage());
        }
    }
}

if (!function_exists('rx_ui_marker_section')) {
    function rx_ui_marker_section($markup): ?string
    {
        if (is_string($markup) && $markup !== '' && strpos($markup, '"_rxsec"') !== false) {
            $markup = json_decode($markup, true);
        }
        if (is_array($markup) && isset($markup['_rxsec']) && is_string($markup['_rxsec']) && isset(rx_ui_section_catalog()[$markup['_rxsec']])) {
            return $markup['_rxsec'];
        }
        return null;
    }
}

if (!function_exists('rx_ui_mark_keyboard')) {
    function rx_ui_mark_keyboard($keyboard, string $section)
    {
        if (!is_string($keyboard) || $keyboard === '' || !isset(rx_ui_section_catalog()[$section])) {
            return $keyboard;
        }
        $decoded = json_decode($keyboard, true);
        if (!is_array($decoded)) {
            return $keyboard;
        }
        $decoded['_rxsec'] = $section;
        return json_encode($decoded, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }
}

if (!function_exists('rx_ui_classify_markup')) {
    function rx_ui_classify_markup($markup): ?string
    {
        if (is_string($markup) && $markup !== '') {
            $markup = json_decode($markup, true);
        }
        if (!is_array($markup) || empty($markup['inline_keyboard']) || !is_array($markup['inline_keyboard'])) {
            return null;
        }
        foreach ($markup['inline_keyboard'] as $row) {
            foreach ((array) $row as $btn) {
                if (is_array($btn) && isset($btn['callback_data'])) {
                    $section = rx_ui_route_callback($btn['callback_data']);
                    if ($section !== null) {
                        return $section;
                    }
                }
            }
        }
        return null;
    }
}

if (!function_exists('rx_ui_section_for_send')) {
    function rx_ui_section_for_send($chatId, $markup = null, $explicit = null): string
    {
        $catalog = rx_ui_section_catalog();
        if (is_string($explicit) && isset($catalog[$explicit])) {
            return $explicit;
        }
        $marker = rx_ui_marker_section($markup);
        if ($marker !== null) {
            return $marker;
        }
        $chatId = trim((string) $chatId);
        $actor = isset($GLOBALS['from_id']) ? trim((string) $GLOBALS['from_id']) : '';
        if ($actor !== '' && $chatId === $actor && !empty($GLOBALS['update'])) {
            $ctx = $GLOBALS['rx_ui_section'] ?? null;
            return is_string($ctx) && isset($catalog[$ctx]) ? $ctx : 'main_menu';
        }
        $classified = rx_ui_classify_markup($markup);
        if ($classified !== null) {
            return $classified;
        }
        if ($chatId !== '' && ctype_digit($chatId) && function_exists('select')) {
            try {
                $stored = select('user', 'ui_section', 'id', $chatId, 'select');
                if (is_string($stored) && isset($catalog[$stored])) {
                    return $stored;
                }
            } catch (Throwable $e) {
            }
        }
        return 'main_menu';
    }
}

if (!function_exists('rx_richActiveForSend')) {
    function rx_richActiveForSend($chatId, $markup = null, $explicit = null): bool
    {
        if (!function_exists('rx_richUserButtonsOn') || !rx_richUserButtonsOn() || !function_exists('rx_richUi_chatIsUserUi') || !rx_richUi_chatIsUserUi($chatId)) {
            return false;
        }
        return rx_richSectionActive(rx_ui_section_for_send($chatId, $markup, $explicit));
    }
}

if (!function_exists('rx_ui_track_reply_keyboard')) {
    function rx_ui_track_reply_keyboard($datas, $result): void
    {
        try {
            if (!is_array($datas) || !is_array($result) || empty($result['ok']) || !function_exists('rx_richUserButtonsOn') || !rx_richUserButtonsOn()) {
                return;
            }
            $markup = $datas['reply_markup'] ?? null;
            if (is_string($markup) && $markup !== '') {
                $markup = json_decode($markup, true);
            }
            if (!is_array($markup) || empty($markup['keyboard']) || !isset($datas['chat_id']) || !rx_richUi_chatIsUserUi($datas['chat_id'])) {
                return;
            }
            $chat = (string) $datas['chat_id'];
            $flag = select('user', 'reply_kb_cleared', 'id', $chat, 'select', ['cache' => false]);
            if (is_scalar($flag) && (string) $flag === '1') {
                update('user', 'reply_kb_cleared', '0', 'id', $chat);
            }
        } catch (Throwable $e) {
        }
    }
}

if (!function_exists('rx_ui_after_send')) {
    function rx_ui_after_send($method, $datas, $result): void
    {
        rx_ui_track_reply_keyboard($datas, $result);
        if (function_exists('rx_decor_after_send')) {
            rx_decor_after_send($method, $datas, $result);
        }
    }
}

if (!function_exists('rx_ui_sections_mutate')) {
    function rx_ui_sections_mutate(string $action, string $id = '', string $embedded = ''): array
    {
        global $pdo;
        $catalog = rx_ui_section_catalog();
        if (!($pdo instanceof PDO)) {
            return ['ok' => false, 'changed' => false, 'stale' => false];
        }
        if ($action === 'toggle' && !isset($catalog[$id])) {
            return ['ok' => false, 'changed' => false, 'stale' => false];
        }
        try {
            $check = $pdo->prepare('SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = ? AND column_name = ?');
            $check->execute(['setting', 'user_rich_sections']);
            if ((int) $check->fetchColumn() === 0) {
                $pdo->exec('ALTER TABLE `setting` ADD `user_rich_sections` TEXT NULL');
            }
            $pdo->beginTransaction();
            $raw = $pdo->query('SELECT user_rich_sections FROM setting LIMIT 1 FOR UPDATE')->fetchColumn();
            $current = rx_ui_parse_selection($raw === false ? null : $raw)['ids'];
            $next = $current;
            $stale = false;
            if ($action === 'all') {
                $next = array_keys($catalog);
            } elseif ($action === 'none') {
                $next = [];
            } else {
                $isOn = in_array($id, $current, true);
                if ($embedded !== ($isOn ? '1' : '0')) {
                    $stale = true;
                } else {
                    $next = $isOn ? array_values(array_diff($current, [$id])) : array_merge($current, [$id]);
                }
            }
            $ordered = array_values(array_filter(array_keys($catalog), static function ($key) use ($next) {
                return in_array($key, $next, true);
            }));
            $changed = !$stale && ($raw === null || $raw === false || trim((string) $raw) === '' || $ordered !== $current || json_encode($ordered) !== (string) $raw);
            if ($changed) {
                $pdo->prepare('UPDATE setting SET user_rich_sections = ?')->execute([json_encode($ordered)]);
            }
            $pdo->commit();
            return ['ok' => true, 'changed' => $changed, 'stale' => $stale];
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            error_log('[ui_sections] mutate failed: ' . $e->getMessage());
            return ['ok' => false, 'changed' => false, 'stale' => false];
        }
    }
}

if (!function_exists('rxRenderRichSections')) {
    function rxRenderRichSections($from_id): void
    {
        global $setting;
        $catalog = rx_ui_section_catalog();
        $selection = rx_ui_selection();
        $rows = [];
        foreach ($catalog as $id => $label) {
            $on = in_array($id, $selection['ids'], true);
            $rows[] = [['text' => ($on ? '✅ ' : '❌ ') . $label, 'callback_data' => 'richsec_t_' . $id . '_' . ($on ? '1' : '0')]];
        }
        $rows[] = [
            ['text' => 'انتخاب همه', 'callback_data' => 'richsec_all'],
            ['text' => 'لغو انتخاب همه', 'callback_data' => 'richsec_none'],
        ];
        $rows[] = [['text' => 'بازگشت', 'callback_data' => 'glass_mode_settings']];
        $masterOn = rx_richUserButtonsOn();
        $text = "⚙️ <b>تنظیمات داخلی متن</b>\n\n"
            . "وضعیت دکمه داخل متن پیام: " . ($masterOn ? "✅ روشن" : "❌ خاموش") . "\n\n"
            . "با انتخاب هر بخش، دکمه‌های آن بخش و تمام مراحل وابسته به آن به‌صورت «دکمه داخل متن پیام» نمایش داده می‌شوند. بخش‌های انتخاب‌نشده با حالت عادی (شیشه‌ای یا Reply Keyboard) نمایش داده می‌شوند.\n"
            . ($masterOn ? "" : "\n💡 تا زمانی که «دکمه داخل متن پیام» خاموش است، انتخاب‌ها ذخیره می‌شوند ولی اعمال نمی‌شوند.\n");
        if (in_array($selection['state'], ['malformed', 'unknown'], true)) {
            $text .= "\n⚠️ تنظیمات ذخیره‌شده نامعتبر است و موقتاً همه بخش‌ها (یا فقط بخش‌های معتبر) در نظر گرفته می‌شوند. با تغییر انتخاب، تنظیمات اصلاح می‌شود.\n";
        }
        nm_adminInstantReply($from_id, $text, json_encode(['inline_keyboard' => $rows], JSON_UNESCAPED_UNICODE), 'HTML');
    }
}

if (!function_exists('rx_ui_sections_admin_action')) {
    function rx_ui_sections_admin_action(string $datain, $from_id, bool $authorized, $callbackQueryId = null): bool
    {
        if (!preg_match('/^richsec_(menu|all|none|t_([a-z_]+)_([01]))$/', $datain, $m)) {
            return false;
        }
        if (!$authorized) {
            if (!empty($callbackQueryId)) {
                @telegram('answerCallbackQuery', ['callback_query_id' => $callbackQueryId, 'text' => 'شما دسترسی تغییر این تنظیم را ندارید.', 'show_alert' => true]);
            }
            return true;
        }
        $outcome = null;
        if ($m[1] === 'all') {
            $outcome = rx_ui_sections_mutate('all');
        } elseif ($m[1] === 'none') {
            $outcome = rx_ui_sections_mutate('none');
        } elseif (isset($m[2]) && $m[2] !== '') {
            $outcome = rx_ui_sections_mutate('toggle', $m[2], $m[3]);
        }
        if ($outcome !== null) {
            if (function_exists('rx_richUi_refreshSettings')) {
                rx_richUi_refreshSettings();
            }
            if (!empty($callbackQueryId) && !empty($outcome['stale'])) {
                @telegram('answerCallbackQuery', ['callback_query_id' => $callbackQueryId, 'text' => 'وضعیت تغییر کرده بود؛ صفحه به‌روز شد.']);
            }
        }
        rxRenderRichSections($from_id);
        return true;
    }
}

require_once __DIR__ . '/tonpay_templates.php';

const ATLASPAY_CUSTOM_DEADLINE_SECONDS = 1200;
const ATLASPAY_CUSTOM_DEADLINE_GRACE_SECONDS = 600;
const ATLASPAY_CUSTOM_LATE_RECONCILE_SECONDS = 172800;
const ATLASPAY_CUSTOM_POLL_THROTTLE_SECONDS = 8;
const ATLASPAY_CUSTOM_CARD_RETENTION_SECONDS = 10800;
const ATLASPAY_CUSTOM_RECHECK_SECONDS = 900;
const ATLASPAY_CUSTOM_CRON_INTERVAL_SECONDS = 30;
const ATLASPAY_CUSTOM_PENDING_VISIBLE_SECONDS = 7200;
const ATLASPAY_CUSTOM_DEFAULT_TITLE = 'پرداخت کارت‌به‌کارت (اطلس‌پی)';

function atlaspayPaymentMode()
{
    $row = select("PaySetting", "ValuePay", "NamePay", "atlaspay_payment_mode", "select");
    $mode = is_array($row) ? strtolower(trim((string) ($row['ValuePay'] ?? ''))) : '';
    return $mode === 'custom' ? 'custom' : 'official';
}

function atlaspayCustomSaveSetting($name, $value)
{
    global $pdo;
    if (!($pdo instanceof PDO)) {
        return false;
    }
    try {
        $exists = $pdo->prepare("SELECT COUNT(*) FROM PaySetting WHERE NamePay = ?");
        $exists->execute([(string) $name]);
        if ((int) $exists->fetchColumn() > 0) {
            $stmt = $pdo->prepare("UPDATE PaySetting SET ValuePay = ? WHERE NamePay = ?");
        } else {
            $stmt = $pdo->prepare("INSERT INTO PaySetting (ValuePay, NamePay) VALUES (?, ?)");
        }
        $stmt->execute([(string) $value, (string) $name]);
        if (function_exists('clearSelectCacheRow')) {
            clearSelectCacheRow('PaySetting', 'NamePay', (string) $name);
        }
        return true;
    } catch (Throwable $e) {
        error_log('AtlasPay setting save failed: ' . $e->getMessage());
        return false;
    }
}

function atlaspayCustomWebhookSecret()
{
    $row = select("PaySetting", "ValuePay", "NamePay", "atlaspay_webhook_secret", "select");
    return is_array($row) ? trim((string) ($row['ValuePay'] ?? '')) : '';
}

function atlaspayCustomWebhookUrl()
{
    global $domainhosts;
    return 'https://' . $domainhosts . '/payment/atlaspay.php';
}

function atlaspayCustomRegisterWebhook()
{
    $apiKey = atlaspayApiKey();
    if ($apiKey === '') {
        return ['ok' => false, 'message' => 'کلید API اطلس‌پی ثبت نشده است.'];
    }
    $url = atlaspayCustomWebhookUrl();
    $current = atlaspayCurlJson('GET', ATLASPAY_BASE_URL . '/webhook', [], $apiKey);
    if (!is_array($current)) {
        return ['ok' => false, 'message' => 'ارتباط با اطلس‌پی برقرار نشد.'];
    }
    $statusCode = (int) ($current['status_code'] ?? 0);
    if ($statusCode < 200 || $statusCode >= 300) {
        return ['ok' => false, 'message' => 'دریافت وضعیت Webhook از اطلس‌پی ناموفق بود.'];
    }
    $data = isset($current['data']) && is_array($current['data']) ? $current['data'] : $current;
    $existing = isset($data['webhookUrl']) && is_scalar($data['webhookUrl']) ? trim((string) $data['webhookUrl']) : '';
    if ($existing !== '' && $existing !== $url) {
        return ['ok' => false, 'code' => 'foreign', 'message' => 'یک آدرس Webhook دیگر روی حساب اطلس‌پی ثبت شده و بازنویسی نشد؛ تأیید پرداخت‌ها فقط با استعلام دوره‌ای انجام می‌شود.'];
    }
    if ($existing === $url && atlaspayCustomWebhookSecret() !== '') {
        return ['ok' => true, 'message' => 'Webhook از قبل ثبت شده است.'];
    }
    $registered = atlaspayCurlJson('POST', ATLASPAY_BASE_URL . '/webhook', ['webhookUrl' => $url], $apiKey);
    if (!is_array($registered)) {
        return ['ok' => false, 'message' => 'ثبت Webhook در اطلس‌پی ناموفق بود.'];
    }
    $registeredCode = (int) ($registered['status_code'] ?? 0);
    $registeredData = isset($registered['data']) && is_array($registered['data']) ? $registered['data'] : $registered;
    $secret = isset($registeredData['webhookSecret']) && is_scalar($registeredData['webhookSecret']) ? trim((string) $registeredData['webhookSecret']) : '';
    if ($registeredCode < 200 || $registeredCode >= 300 || $secret === '') {
        return ['ok' => false, 'message' => 'ثبت Webhook در اطلس‌پی ناموفق بود.'];
    }
    if (!atlaspayCustomSaveSetting('atlaspay_webhook_secret', $secret)) {
        return ['ok' => false, 'message' => 'ذخیره کلید امضای Webhook ناموفق بود.'];
    }
    return ['ok' => true, 'message' => 'Webhook با موفقیت ثبت شد.'];
}

function atlaspayCustomVerifyWebhookSignature($rawBody, $signature)
{
    $secret = atlaspayCustomWebhookSecret();
    $signature = strtolower(trim((string) $signature));
    if (strpos($signature, 'sha256=') === 0) {
        $signature = substr($signature, 7);
    }
    if ($secret === '' || $signature === '') {
        return false;
    }
    $candidates = [hash_hmac('sha256', (string) $rawBody, $secret)];
    $decoded = json_decode((string) $rawBody, true);
    if (is_array($decoded)) {
        $candidates[] = hash_hmac('sha256', json_encode($decoded, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), $secret);
    }
    foreach ($candidates as $candidate) {
        if (hash_equals($candidate, $signature)) {
            return true;
        }
    }
    return false;
}

function atlaspayCustomError($message, $code = '')
{
    return ['success' => false, 'error' => (string) $message, 'error_code' => (string) $code];
}

function atlaspayCustomParseTime($value)
{
    if (!is_string($value) || trim($value) === '') {
        return 0;
    }
    $ts = strtotime($value);
    return $ts === false ? 0 : (int) $ts;
}

function atlaspayCustomValidReceiptUrl($url)
{
    $url = is_scalar($url) ? trim((string) $url) : '';
    if ($url === '' || strlen($url) > 500) {
        return '';
    }
    $parts = parse_url($url);
    if (!is_array($parts) || strtolower((string) ($parts['scheme'] ?? '')) !== 'https') {
        return '';
    }
    if (!in_array(strtolower((string) ($parts['host'] ?? '')), ['t.me', 'telegram.me'], true)) {
        return '';
    }
    if (isset($parts['user']) || isset($parts['pass']) || isset($parts['port'])) {
        return '';
    }
    return $url;
}

function atlaspayCustomCardIsComplete($cardNumber)
{
    $raw = (string) $cardNumber;
    if (preg_match('/^[\d\s\-]{16,23}$/', $raw) !== 1) {
        return false;
    }
    return strlen(preg_replace('/\D/', '', $raw)) === 16;
}

function atlaspayCustomCreateOrder($orderId, $amount, $telegramId)
{
    $amount = (int) $amount;
    $telegramId = (int) $telegramId;
    $decoded = atlaspayCreateOrder($orderId, $amount, $telegramId > 0 ? $telegramId : null);
    if (!is_array($decoded) || (isset($decoded['success']) && $decoded['success'] === false)) {
        return atlaspayCustomError(is_array($decoded) ? (string) ($decoded['error'] ?? 'پاسخ نامعتبر از سرویس اطلس‌پی') : 'پاسخ نامعتبر از سرویس اطلس‌پی');
    }
    $remoteId = trim((string) ($decoded['orderId'] ?? ''));
    $discard = static function () use ($remoteId) {
        if ($remoteId !== '' && function_exists('atlaspayCancelOrder')) {
            atlaspayCancelOrder($remoteId);
        }
    };
    $total = $decoded['totalAmountToman'] ?? null;
    if (!is_numeric($total) || (float) $total != floor((float) $total) || (int) $total < $amount) {
        $discard();
        error_log('AtlasPay custom create order amount mismatch: ' . json_encode(['order_id' => (string) $orderId, 'requested' => $amount, 'total' => $total], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return atlaspayCustomError('مبلغ سفارش اطلس‌پی با مبلغ درخواستی مطابقت ندارد', 'AMOUNT_MISMATCH');
    }
    if (isset($decoded['baseAmountToman']) && is_numeric($decoded['baseAmountToman']) && (int) $decoded['baseAmountToman'] !== $amount) {
        $discard();
        error_log('AtlasPay custom create order base mismatch: ' . json_encode(['order_id' => (string) $orderId, 'requested' => $amount, 'base' => $decoded['baseAmountToman']], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return atlaspayCustomError('مبلغ سفارش اطلس‌پی با مبلغ درخواستی مطابقت ندارد', 'AMOUNT_MISMATCH');
    }
    $link = atlaspayCustomValidReceiptUrl($decoded['customerStartLink'] ?? '');
    if ($link === '') {
        $discard();
        return atlaspayCustomError('لینک رسمی اطلس‌پی معتبر نیست', 'INVALID_LINK');
    }
    $card = isset($decoded['cardNumber']) && is_scalar($decoded['cardNumber']) ? substr(trim((string) $decoded['cardNumber']), 0, 40) : '';
    if (!atlaspayCustomCardIsComplete($card)) {
        $card = '';
    }
    $deadline = atlaspayCustomParseTime($decoded['paymentDeadlineAt'] ?? '');
    return [
        'orderId' => $remoteId,
        'trackingCode' => isset($decoded['trackingCode']) && is_scalar($decoded['trackingCode']) ? substr(trim((string) $decoded['trackingCode']), 0, 64) : '',
        'customerStartLink' => $link,
        'totalAmountToman' => (int) $total,
        'baseAmountToman' => $amount,
        'cardNumber' => $card,
        'cardHolderName' => isset($decoded['cardHolderName']) && is_scalar($decoded['cardHolderName']) ? mb_substr(trim((string) $decoded['cardHolderName']), 0, 120) : '',
        'bankName' => isset($decoded['bankName']) && is_scalar($decoded['bankName']) ? mb_substr(trim((string) $decoded['bankName']), 0, 80) : '',
        'paymentDeadlineAt' => $deadline,
    ];
}

function atlaspayCustomFetchReport($orderId)
{
    global $pdo;
    if (!($pdo instanceof PDO)) {
        return null;
    }
    try {
        $stmt = $pdo->prepare(
            "SELECT * FROM Payment_report
              WHERE id_order = ? AND Payment_Method = 'atlaspay' AND atlaspay_gateway_mode = 'custom'
              LIMIT 1"
        );
        $stmt->execute([(string) $orderId]);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return is_array($row) ? $row : null;
    } catch (Throwable $e) {
        error_log('AtlasPay custom fetch report failed: ' . $e->getMessage());
        return null;
    }
}

function atlaspayCustomStoreOrder($orderId, array $order)
{
    global $pdo;
    if (!($pdo instanceof PDO)) {
        return false;
    }
    $now = time();
    $deadline = (int) $order['paymentDeadlineAt'];
    if ($deadline <= $now) {
        $deadline = $now + ATLASPAY_CUSTOM_DEADLINE_SECONDS;
    }
    try {
        $stmt = $pdo->prepare(
            "UPDATE Payment_report
                SET atlaspay_gateway_mode = 'custom',
                    atlaspay_order_id = ?,
                    atlaspay_tracking_code = ?,
                    atlaspay_payment_url = ?,
                    atlaspay_total_amount = ?,
                    atlaspay_card_number = ?,
                    atlaspay_card_name = ?,
                    atlaspay_bank_name = ?,
                    atlaspay_remote_status = 'awaiting_payment',
                    atlaspay_created_at = ?,
                    atlaspay_deadline_at = ?,
                    atlaspay_local_state = 'awaiting_payment',
                    atlaspay_last_checked_at = ?
              WHERE id_order = ?"
        );
        $stmt->execute([
            $order['orderId'],
            $order['trackingCode'],
            $order['customerStartLink'],
            $order['totalAmountToman'],
            $order['cardNumber'],
            $order['cardHolderName'],
            $order['bankName'],
            $now,
            $deadline,
            $now,
            (string) $orderId,
        ]);
        return $stmt->rowCount() > 0;
    } catch (Throwable $e) {
        error_log('AtlasPay custom store order failed: ' . json_encode(['order_id' => (string) $orderId, 'error' => $e->getMessage()], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return false;
    }
}

function atlaspayCustomUpdateColumns($orderId, array $columns, $onlyOpen = true)
{
    global $pdo;
    if (!($pdo instanceof PDO) || empty($columns)) {
        return 0;
    }
    $sets = [];
    $params = [];
    foreach ($columns as $name => $value) {
        $sets[] = $name . ' = ?';
        $params[] = $value;
    }
    $params[] = (string) $orderId;
    $sql = "UPDATE Payment_report SET " . implode(', ', $sets) . " WHERE id_order = ? AND atlaspay_gateway_mode = 'custom'";
    if ($onlyOpen) {
        $sql .= " AND payment_Status IN ('Unpaid','pending','waiting')";
    }
    try {
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        if (function_exists('clearSelectCacheRow')) {
            clearSelectCacheRow('Payment_report', 'id_order', (string) $orderId);
        }
        if (function_exists('rx_redis_del')) {
            $owner = select('Payment_report', 'id_user', 'id_order', (string) $orderId, 'select');
            if (is_array($owner)) {
                rx_redis_del('faoxima:paystatus:' . (string) $orderId . ':' . (string) ($owner['id_user'] ?? ''));
            }
        }
        return $stmt->rowCount();
    } catch (Throwable $e) {
        error_log('AtlasPay custom update failed: ' . json_encode(['order_id' => (string) $orderId, 'error' => $e->getMessage()], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return 0;
    }
}

function atlaspayCustomTransition($orderId, array $fromStatuses, $toStatus, $localState, array $extra = [])
{
    global $pdo;
    if (!($pdo instanceof PDO) || empty($fromStatuses)) {
        return false;
    }
    $sets = ['payment_Status = ?', 'atlaspay_local_state = ?'];
    $params = [(string) $toStatus, (string) $localState];
    foreach ($extra as $name => $value) {
        $sets[] = $name . ' = ?';
        $params[] = $value;
    }
    $params[] = (string) $orderId;
    foreach ($fromStatuses as $status) {
        $params[] = (string) $status;
    }
    try {
        $stmt = $pdo->prepare(
            "UPDATE Payment_report SET " . implode(', ', $sets)
            . " WHERE id_order = ? AND atlaspay_gateway_mode = 'custom' AND payment_Status IN (" . implode(',', array_fill(0, count($fromStatuses), '?')) . ")"
        );
        $stmt->execute($params);
        $changed = $stmt->rowCount() > 0;
        if ($changed) {
            if (function_exists('clearSelectCacheRow')) {
                clearSelectCacheRow('Payment_report', 'id_order', (string) $orderId);
            }
            if (function_exists('rx_redis_del')) {
                $owner = select('Payment_report', 'id_user', 'id_order', (string) $orderId, 'select');
                if (is_array($owner)) {
                    rx_redis_del('faoxima:paystatus:' . (string) $orderId . ':' . (string) ($owner['id_user'] ?? ''));
                }
            }
        }
        return $changed;
    } catch (Throwable $e) {
        error_log('AtlasPay custom transition failed: ' . json_encode(['order_id' => (string) $orderId, 'error' => $e->getMessage()], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return false;
    }
}

function atlaspayCustomClaimLocalState($orderId, $state, array $statuses)
{
    global $pdo;
    if (!($pdo instanceof PDO) || empty($statuses)) {
        return false;
    }
    try {
        $stmt = $pdo->prepare(
            "UPDATE Payment_report
                SET atlaspay_local_state = ?
              WHERE id_order = ?
                AND atlaspay_gateway_mode = 'custom'
                AND payment_Status IN (" . implode(',', array_fill(0, count($statuses), '?')) . ")
                AND (atlaspay_local_state IS NULL OR atlaspay_local_state <> ?)"
        );
        $stmt->execute(array_merge([(string) $state, (string) $orderId], array_map('strval', $statuses), [(string) $state]));
        $changed = $stmt->rowCount() > 0;
        if ($changed && function_exists('clearSelectCacheRow')) {
            clearSelectCacheRow('Payment_report', 'id_order', (string) $orderId);
        }
        return $changed;
    } catch (Throwable $e) {
        error_log('AtlasPay custom claim state failed: ' . json_encode(['order_id' => (string) $orderId, 'error' => $e->getMessage()], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        return false;
    }
}

function atlaspayCustomPurchaseKind($invoiceField)
{
    $tag = strpos((string) $invoiceField, '|') !== false ? trim((string) explode('|', (string) $invoiceField, 2)[0]) : '';
    $kinds = [
        'getconfigafterpay' => 'خرید سرویس',
        'getextenduser' => 'تمدید سرویس',
        'getextratimeuser' => 'خرید زمان اضافه',
        'getextravolumeuser' => 'خرید حجم اضافه',
    ];
    return $kinds[$tag] ?? 'شارژ کیف پول';
}

function atlaspayCustomGatewayTitle()
{
    $stored = function_exists('faoxima_textbot_get') ? (string) faoxima_textbot_get('atlaspay', '') : '';
    $name = preg_replace('/^[\s\x{200B}-\x{200F}\x{202A}-\x{202E}\x{FEFF}]+|[\s\x{200B}-\x{200F}\x{202A}-\x{202E}\x{FEFF}]+$/u', '', $stored);
    if (!is_string($name) || $name === '' || $name === '🌐 اطلس‌پی') {
        return ATLASPAY_CUSTOM_DEFAULT_TITLE;
    }
    $stripped = preg_replace('/^(?:💠|🌐)\s*/u', '', $name);
    $name = is_string($stripped) && $stripped !== '' ? $stripped : $name;
    return mb_substr($name, 0, 120);
}

